                <el-form-item label="蜜蜂">
                  <el-select v-model="worldSettings.bees" placeholder="请选择蜜蜂数量" style="width: 100%">
                    <el-option label="无" value="none"></el-option>
                    <el-option label="很少" value="rare"></el-option>
