<script>
export default {
  name: 'ServerSettings',
  data() {
    return {
      loading: false,
      selectedServer: null,
      activeTab: 'basic',
      serverList: [
        {
          id: 1,
          name: '主世界服务器',
          status: 'online'
        },
        {
          id: 2,
          name: '洞穴服务器',
          status: 'online'
        },
        {
          id: 3,
          name: '模组服务器',
          status: 'restarting'
        },
        {
          id: 4,
          name: 'PVP服务器',
          status: 'offline'
        }
      ],
      basicSettings: {
        worldName: '',
        gameMode: 'survival',
        season: 'autumn',
        maxPlayers: 16,
        pvp: false,
        pauseWhenEmpty: true,
        whitelist: false,
        autoBackupInterval: '180',
        consoleCommands: ''
      },
      worldSettings: {
        worldSize: 'medium',
        branchingPathLength: 5,
        loopPercent: 25,
        berryBushes: 'default',
        carrots: 'default',
        rocks: 'default',
        trees: 'default',
        bees: 'default',
        rabbits: 'default',
        pigs: 'default',
        hounds: 'default'
      },
      advancedSettings: {
        cmdLineArgs: '-console -bind_ip 0.0.0.0',
        clusterId: 'cluster_1',
        clusterKey: 'random_key_12345',
        serverPort: 10999,
        maxSnapshots: 10,
        perfTracking: false,
        logLevel: 'info'
      },
      originalSettings: {
        basic: {},
        world: {},
        advanced: {}
      }
    };
  },
  methods: {
    getStatusType(status) {
      const statusMap = {
        'online': 'success',
        'offline': 'info',
        'restarting': 'warning'
      };
      return statusMap[status] || 'info';
    },
    getStatusText(status) {
      const statusMap = {
        'online': '在线',
        'offline': '离线',
        'restarting': '重启中'
      };
      return statusMap[status] || status;
    },
    refreshData() {
      this.loading = true;
      setTimeout(() => {
        this.$message({
          message: '服务器设置已刷新',
          type: 'success'
        });
        this.loading = false;
      }, 800);
    },
    loadServerSettings(serverId) {
      this.loading = true;
      
      // 模拟加载所选服务器的设置数据
      setTimeout(() => {
        // 根据选中的服务器 ID 设置不同的值
        if (serverId === 1) { // 主世界服务器
          this.basicSettings = {
            worldName: '生存世界',
            gameMode: 'survival',
            season: 'autumn',
            maxPlayers: 16,
            pvp: false,
            pauseWhenEmpty: true,
            whitelist: false,
            autoBackupInterval: '180',
            consoleCommands: 'c_announce("欢迎来到主世界服务器!")'
          };
          this.worldSettings = {
            worldSize: 'large',
            branchingPathLength: 6,
            loopPercent: 30,
            berryBushes: 'more',
            carrots: 'more',
            rocks: 'default',
            trees: 'more',
            bees: 'more',
            rabbits: 'default',
            pigs: 'more',
            hounds: 'default'
          };
          this.advancedSettings = {
            cmdLineArgs: '-console -bind_ip 0.0.0.0',
            clusterId: 'cluster_1',
            clusterKey: 'main_world_key_123',
            serverPort: 10999,
            maxSnapshots: 15,
            perfTracking: false,
            logLevel: 'info'
          };
        } else if (serverId === 2) { // 洞穴服务器
          this.basicSettings = {
            worldName: '洞穴世界',
            gameMode: 'survival',
            season: 'autumn',
            maxPlayers: 16,
            pvp: false,
            pauseWhenEmpty: true,
            whitelist: false,
            autoBackupInterval: '180',
            consoleCommands: 'c_announce("欢迎来到洞穴服务器!")'
          };
          this.worldSettings = {
            worldSize: 'medium',
            branchingPathLength: 5,
            loopPercent: 25,
            berryBushes: 'rare',
            carrots: 'none',
            rocks: 'more',
            trees: 'rare',
            bees: 'none',
            rabbits: 'none',
            pigs: 'rare',
            hounds: 'rare'
          };
          this.advancedSettings = {
            cmdLineArgs: '-console -bind_ip 0.0.0.0 -cave',
            clusterId: 'cluster_1',
            clusterKey: 'main_world_key_123',
            serverPort: 11000,
            maxSnapshots: 15,
            perfTracking: false,
            logLevel: 'info'
          };
        } else if (serverId === 3) { // 模组服务器
          this.basicSettings = {
            worldName: '模组世界',
            gameMode: 'endless',
            season: 'spring',
            maxPlayers: 20,
            pvp: false,
            pauseWhenEmpty: true,
            whitelist: true,
            autoBackupInterval: '60',
            consoleCommands: 'c_announce("欢迎来到模组服务器!")'
          };
          this.worldSettings = {
            worldSize: 'huge',
            branchingPathLength: 8,
            loopPercent: 35,
            berryBushes: 'lots',
            carrots: 'lots',
            rocks: 'lots',
            trees: 'lots',
            bees: 'lots',
            rabbits: 'lots',
            pigs: 'lots',
            hounds: 'rare'
          };
          this.advancedSettings = {
            cmdLineArgs: '-console -bind_ip 0.0.0.0 -mods workshop-12345,workshop-67890',
            clusterId: 'modded_cluster',
            clusterKey: 'modded_key_456',
            serverPort: 11001,
            maxSnapshots: 20,
            perfTracking: true,
            logLevel: 'debug'
          };
        } else if (serverId === 4) { // PVP服务器
          this.basicSettings = {
            worldName: 'PVP竞技场',
            gameMode: 'wilderness',
            season: 'winter',
            maxPlayers: 32,
            pvp: true,
            pauseWhenEmpty: false,
            whitelist: false,
            autoBackupInterval: '360',
            consoleCommands: 'c_announce("欢迎来到PVP服务器!")'
          };
          this.worldSettings = {
            worldSize: 'medium',
            branchingPathLength: 4,
            loopPercent: 60,
            berryBushes: 'default',
            carrots: 'default',
            rocks: 'more',
            trees: 'default',
            bees: 'default',
            rabbits: 'default',
            pigs: 'default',
            hounds: 'more'
          };
          this.advancedSettings = {
            cmdLineArgs: '-console -bind_ip 0.0.0.0 -pvp',
            clusterId: 'pvp_cluster',
            clusterKey: 'pvp_key_789',
            serverPort: 11002,
            maxSnapshots: 5,
            perfTracking: true,
            logLevel: 'warning'
          };
        }
        
        // 保存原始设置以便重置
        this.originalSettings = {
          basic: JSON.parse(JSON.stringify(this.basicSettings)),
          world: JSON.parse(JSON.stringify(this.worldSettings)),
          advanced: JSON.parse(JSON.stringify(this.advancedSettings))
        };
        
        this.loading = false;
      }, 800);
    },
    resetSettings() {
      this.$confirm('确定要重置所有设置到最后保存的状态吗?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.basicSettings = JSON.parse(JSON.stringify(this.originalSettings.basic));
        this.worldSettings = JSON.parse(JSON.stringify(this.originalSettings.world));
        this.advancedSettings = JSON.parse(JSON.stringify(this.originalSettings.advanced));
        
        this.$message({
          type: 'success',
          message: '已重置设置'
        });
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消重置'
        });
      });
    },
    saveSettings() {
      this.loading = true;
      setTimeout(() => {
        this.originalSettings = {
          basic: JSON.parse(JSON.stringify(this.basicSettings)),
          world: JSON.parse(JSON.stringify(this.worldSettings)),
          advanced: JSON.parse(JSON.stringify(this.advancedSettings))
        };
        
        this.loading = false;
        
        this.$message({
          message: '服务器设置已保存',
          type: 'success'
        });
      }, 1000);
    }
  }
};
</script>

