<template>
  <div class="page-container">
    <el-card class="main-card">
      <div slot="header" class="clearfix">
        <span>服务器管理</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="refreshData">刷新</el-button>
      </div>

      <!-- 工具栏 -->
      <div class="tool-bar">
        <el-button type="primary" icon="el-icon-plus" @click="dialogVisible = true">添加服务器</el-button>
        <el-button type="success" icon="el-icon-refresh" @click="handleBatchRestart" :disabled="!hasSelection">批量重启</el-button>
        <el-button type="warning" icon="el-icon-turn-off" @click="handleBatchStop" :disabled="!hasSelection">批量关闭</el-button>
      </div>

      <!-- 服务器表格 -->
      <el-table
        :data="serverList"
        v-loading="loading"
        style="width: 100%"
        border
        @selection-change="handleSelectionChange"
        :row-class-name="tableRowClassName"
        highlight-current-row>
        <el-table-column type="selection" width="55"></el-table-column>
        <el-table-column label="服务器" min-width="240">
          <template slot-scope="scope">
            <div class="server-name">
              <el-tag size="small" :type="getStatusType(scope.row.status)" class="status-tag">
                {{ getStatusText(scope.row.status) }}
              </el-tag>
              <span class="server-title">{{ scope.row.name }}</span>
              <el-tag size="small" type="warning" v-if="scope.row.season" class="season-tag">{{ scope.row.season }}</el-tag>
            </div>
            <div class="server-address">
              <i class="el-icon-position"></i>
              <span>{{ scope.row.address }}</span>
              <el-button size="mini" type="text" @click="copyAddress(scope.row.address)">复制</el-button>
            </div>
          </template>
        </el-table-column>
        <el-table-column prop="type" label="类型" width="120">
          <template slot-scope="scope">
            <el-tag size="medium" :type="getServerTypeTag(scope.row.type)">{{ scope.row.type }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="version" label="版本" width="100" align="center"></el-table-column>
        <el-table-column prop="players" label="在线玩家" width="100" align="center">
          <template slot-scope="scope">
            <el-badge :value="scope.row.players.length" :max="99" class="player-badge">
              <el-button size="small" icon="el-icon-user" circle @click="showPlayers(scope.row)"></el-button>
            </el-badge>
          </template>
        </el-table-column>
        <el-table-column prop="uptime" label="运行时间" width="120" align="center"></el-table-column>
        <el-table-column prop="memory" label="内存使用" width="120">
          <template slot-scope="scope">
            <el-progress :percentage="scope.row.memory" :format="format => `${format}%`" :status="getMemoryStatus(scope.row.memory)"></el-progress>
          </template>
        </el-table-column>
        <el-table-column prop="cpu" label="CPU使用" width="120">
          <template slot-scope="scope">
            <el-progress :percentage="scope.row.cpu" :format="format => `${format}%`" :status="getCpuStatus(scope.row.cpu)"></el-progress>
          </template>
        </el-table-column>
        <el-table-column label="操作" width="280" align="center">
          <template slot-scope="scope">
            <el-button size="mini" type="primary" icon="el-icon-edit" @click="handleEdit(scope.row)"></el-button>
            <el-button size="mini" type="success" icon="el-icon-refresh" @click="handleRestart(scope.row)" :disabled="!canRestart(scope.row)"></el-button>
            <el-button size="mini" type="warning" icon="el-icon-video-pause" @click="handleStop(scope.row)" :disabled="scope.row.status === 'offline'"></el-button>
            <el-button size="mini" type="danger" icon="el-icon-delete" @click="handleDelete(scope.row)"></el-button>
            <el-dropdown trigger="click" @command="handleCommand($event, scope.row)">
              <el-button size="mini" type="info">
                更多<i class="el-icon-arrow-down el-icon--right"></i>
              </el-button>
              <el-dropdown-menu slot="dropdown">
                <el-dropdown-item command="console">控制台</el-dropdown-item>
                <el-dropdown-item command="backup" :disabled="scope.row.status === 'offline'">备份存档</el-dropdown-item>
                <el-dropdown-item command="mods">模组管理</el-dropdown-item>
                <el-dropdown-item command="settings">服务器设置</el-dropdown-item>
                <el-dropdown-item command="logs" divided>查看日志</el-dropdown-item>
              </el-dropdown-menu>
            </el-dropdown>
          </template>
        </el-table-column>
      </el-table>
    </el-card>

    <!-- 添加/编辑服务器对话框 -->
    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="600px">
      <el-form :model="serverForm" :rules="serverRules" ref="serverForm" label-width="100px">
        <el-form-item label="服务器名称" prop="name">
          <el-input v-model="serverForm.name" placeholder="请输入服务器名称"></el-input>
        </el-form-item>
        <el-form-item label="服务器地址" prop="address">
          <el-input v-model="serverForm.address" placeholder="请输入服务器地址"></el-input>
        </el-form-item>
        <el-form-item label="服务器类型" prop="type">
          <el-select v-model="serverForm.type" placeholder="请选择服务器类型" style="width: 100%">
            <el-option label="主世界服务器" value="主世界服务器"></el-option>
            <el-option label="洞穴服务器" value="洞穴服务器"></el-option>
            <el-option label="模组服务器" value="模组服务器"></el-option>
            <el-option label="PVP服务器" value="PVP服务器"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="游戏版本" prop="version">
          <el-input v-model="serverForm.version" placeholder="请输入游戏版本"></el-input>
        </el-form-item>
        <el-form-item label="当前季节" prop="season">
          <el-select v-model="serverForm.season" placeholder="请选择当前季节" style="width: 100%">
            <el-option label="春" value="春"></el-option>
            <el-option label="夏" value="夏"></el-option>
            <el-option label="秋" value="秋"></el-option>
            <el-option label="冬" value="冬"></el-option>
            <el-option label="无" value=""></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="自动启动">
          <el-switch v-model="serverForm.autoStart"></el-switch>
        </el-form-item>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" @click="submitServerForm">确认</el-button>
      </span>
    </el-dialog>

    <!-- 在线玩家对话框 -->
    <el-dialog title="在线玩家" :visible.sync="playersVisible" width="500px">
      <div v-if="currentServer && currentServer.players.length === 0" class="empty-players">
        <i class="el-icon-warning-outline"></i>
        <p>当前服务器没有在线玩家</p>
      </div>
      <el-table v-else :data="currentServer ? currentServer.players : []" style="width: 100%">
        <el-table-column prop="name" label="玩家名称"></el-table-column>
        <el-table-column prop="role" label="角色"></el-table-column>
        <el-table-column prop="time" label="在线时长"></el-table-column>
        <el-table-column label="操作" width="150" align="center">
          <template slot-scope="scope">
            <el-button size="mini" type="success" @click="handleMessage(scope.row)">私信</el-button>
            <el-button size="mini" type="warning" @click="handleKick(scope.row)">踢出</el-button>
          </template>
        </el-table-column>
      </el-table>
      <span slot="footer" class="dialog-footer">
        <el-button @click="playersVisible = false">关闭</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'ServerList',
  data() {
    return {
      loading: false,
      serverList: [
        {
          id: 1,
          name: '主世界服务器',
          address: '192.168.1.100:10999',
          type: '主世界服务器',
          version: 'v0.525842',
          status: 'online',
          uptime: '5天12小时',
          memory: 45,
          cpu: 28,
          season: '夏',
          autoStart: true,
          players: [
            { id: 1, name: '猪王爱烤肉', role: '薇诺娜', time: '3小时25分' },
            { id: 2, name: '沃利大厨', role: '沃利', time: '2小时10分' }
          ]
        },
        {
          id: 2,
          name: '洞穴服务器',
          address: '192.168.1.100:11000',
          type: '洞穴服务器',
          version: 'v0.525842',
          status: 'online',
          uptime: '5天12小时',
          memory: 38,
          cpu: 22,
          season: '',
          autoStart: true,
          players: [
            { id: 3, name: '麦斯威尔', role: '麦斯威尔', time: '1小时40分' }
          ]
        },
        {
          id: 3,
          name: '模组服务器',
          address: '192.168.1.100:11001',
          type: '模组服务器',
          version: 'v0.525842',
          status: 'restarting',
          uptime: '0分钟',
          memory: 15,
          cpu: 85,
          season: '秋',
          autoStart: true,
          players: []
        },
        {
          id: 4,
          name: 'PVP服务器',
          address: '192.168.1.100:11002',
          type: 'PVP服务器',
          version: 'v0.525842',
          status: 'offline',
          uptime: '0分钟',
          memory: 0,
          cpu: 0,
          season: '冬',
          autoStart: false,
          players: []
        }
      ],
      selectedServers: [],
      dialogVisible: false,
      dialogTitle: '添加服务器',
      serverForm: {
        id: null,
        name: '',
        address: '',
        type: '主世界服务器',
        version: 'v0.525842',
        status: 'offline',
        uptime: '0分钟',
        memory: 0,
        cpu: 0,
        season: '',
        autoStart: true,
        players: []
      },
      serverRules: {
        name: [
          { required: true, message: '请输入服务器名称', trigger: 'blur' }
        ],
        address: [
          { required: true, message: '请输入服务器地址', trigger: 'blur' }
        ],
        type: [
          { required: true, message: '请选择服务器类型', trigger: 'change' }
        ],
        version: [
          { required: true, message: '请输入游戏版本', trigger: 'blur' }
        ]
      },
      playersVisible: false,
      currentServer: null
    }
  },
  computed: {
    hasSelection() {
      return this.selectedServers.length > 0;
    }
  },
  mounted() {
    this.loading = true;
    setTimeout(() => {
      this.loading = false;
    }, 800);
  },
  methods: {
    refreshData() {
      this.loading = true;
      setTimeout(() => {
        this.$message({
          message: '服务器数据已刷新',
          type: 'success'
        });
        this.loading = false;
      }, 800);
    },
    handleSelectionChange(val) {
      this.selectedServers = val;
    },
    getStatusType(status) {
      const statusMap = {
        'online': 'success',
        'offline': 'info',
        'restarting': 'warning'
      };
      return statusMap[status] || 'info';
    },
    getStatusText(status) {
      const statusMap = {
        'online': '在线',
        'offline': '离线',
        'restarting': '重启中'
      };
      return statusMap[status] || status;
    },
    getServerTypeTag(type) {
      const typeMap = {
        '主世界服务器': 'primary',
        '洞穴服务器': 'success',
        '模组服务器': 'warning',
        'PVP服务器': 'danger'
      };
      return typeMap[type] || '';
    },
    tableRowClassName({ row }) {
      if (row.status === 'offline') {
        return 'server-row-offline';
      } else if (row.status === 'restarting') {
        return 'server-row-restarting';
      }
      return '';
    },
    getMemoryStatus(value) {
      if (value > 80) return 'exception';
      if (value > 60) return 'warning';
      return 'success';
    },
    getCpuStatus(value) {
      if (value > 80) return 'exception';
      if (value > 60) return 'warning';
      return 'success';
    },
    canRestart(row) {
      return row.status !== 'restarting';
    },
    handleEdit(row) {
      this.dialogTitle = '编辑服务器';
      this.serverForm = { ...row };
      this.dialogVisible = true;
    },
    handleRestart(row) {
      this.$confirm(`确定要重启服务器 "${row.name}" 吗?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.loading = true;
        // 模拟重启操作
        const index = this.serverList.findIndex(s => s.id === row.id);
        if (index !== -1) {
          this.serverList[index].status = 'restarting';
          
          setTimeout(() => {
            this.serverList[index].status = 'online';
            this.serverList[index].uptime = '0分钟';
            this.loading = false;
            
            this.$message({
              type: 'success',
              message: `服务器 ${row.name} 已重启成功！`
            });
          }, 3000);
        }
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消重启'
        });
      });
    },
    handleStop(row) {
      this.$confirm(`确定要停止服务器 "${row.name}" 吗?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.loading = true;
        // 模拟停止操作
        const index = this.serverList.findIndex(s => s.id === row.id);
        if (index !== -1) {
          setTimeout(() => {
            this.serverList[index].status = 'offline';
            this.serverList[index].uptime = '0分钟';
            this.serverList[index].memory = 0;
            this.serverList[index].cpu = 0;
            this.serverList[index].players = [];
            this.loading = false;
            
            this.$message({
              type: 'success',
              message: `服务器 ${row.name} 已停止！`
            });
          }, 1500);
        }
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消停止'
        });
      });
    },
    handleDelete(row) {
      this.$confirm(`确定要删除服务器 "${row.name}" 吗? 此操作将无法恢复!`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        // 模拟删除操作
        this.loading = true;
        setTimeout(() => {
          this.serverList = this.serverList.filter(s => s.id !== row.id);
          this.loading = false;
          
          this.$message({
            type: 'success',
            message: `服务器 ${row.name} 已删除！`
          });
        }, 800);
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消删除'
        });
      });
    },
    handleBatchRestart() {
      if (this.selectedServers.length === 0) return;
      
      const names = this.selectedServers.map(s => s.name).join('、');
      this.$confirm(`确定要重启所选的 ${this.selectedServers.length} 台服务器吗?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.loading = true;
        // 模拟批量重启
        setTimeout(() => {
          this.selectedServers.forEach(selected => {
            const index = this.serverList.findIndex(s => s.id === selected.id);
            if (index !== -1 && this.serverList[index].status !== 'offline') {
              this.serverList[index].status = 'restarting';
              
              setTimeout(() => {
                this.serverList[index].status = 'online';
                this.serverList[index].uptime = '0分钟';
              }, 2000 + Math.random() * 3000);
            }
          });
          
          this.loading = false;
          this.$message({
            type: 'success',
            message: `已开始重启所选服务器！`
          });
        }, 1000);
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消操作'
        });
      });
    },
    handleBatchStop() {
      if (this.selectedServers.length === 0) return;
      
      const names = this.selectedServers.map(s => s.name).join('、');
      this.$confirm(`确定要停止所选的 ${this.selectedServers.length} 台服务器吗?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.loading = true;
        // 模拟批量停止
        setTimeout(() => {
          this.selectedServers.forEach(selected => {
            const index = this.serverList.findIndex(s => s.id === selected.id);
            if (index !== -1 && this.serverList[index].status !== 'offline') {
              this.serverList[index].status = 'offline';
              this.serverList[index].uptime = '0分钟';
              this.serverList[index].memory = 0;
              this.serverList[index].cpu = 0;
              this.serverList[index].players = [];
            }
          });
          
          this.loading = false;
          this.$message({
            type: 'success',
            message: `已停止所选服务器！`
          });
        }, 1000);
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消操作'
        });
      });
    },
    copyAddress(address) {
      // 模拟复制到剪贴板
      this.$message({
        message: `已复制地址: ${address}`,
        type: 'success'
      });
    },
    showPlayers(row) {
      this.currentServer = row;
      this.playersVisible = true;
    },
    handleMessage(player) {
      this.$prompt(`发送消息给玩家 ${player.name}`, '私信', {
        confirmButtonText: '发送',
        cancelButtonText: '取消',
        inputPlaceholder: '请输入消息内容'
      }).then(({ value }) => {
        this.$message({
          type: 'success',
          message: `消息已发送给 ${player.name}！`
        });
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消发送'
        });
      });
    },
    handleKick(player) {
      this.$confirm(`确定要将玩家 "${player.name}" 踢出服务器吗?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        // 从当前服务器玩家列表中移除该玩家
        if (this.currentServer) {
          this.currentServer.players = this.currentServer.players.filter(p => p.id !== player.id);
          
          // 更新原服务器列表中的数据
          const index = this.serverList.findIndex(s => s.id === this.currentServer.id);
          if (index !== -1) {
            this.serverList[index].players = [...this.currentServer.players];
          }
          
          this.$message({
            type: 'success',
            message: `已将玩家 ${player.name} 踢出服务器！`
          });
        }
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消操作'
        });
      });
    },
    handleCommand(command, row) {
      switch (command) {
        case 'console':
          this.$message({
            message: `正在打开 ${row.name} 的控制台`,
            type: 'info'
          });
          break;
        case 'backup':
          this.$message({
            message: `正在备份 ${row.name} 的存档`,
            type: 'info'
          });
          break;
        case 'mods':
          this.$router.push('/mods/list');
          break;
        case 'settings':
          this.$router.push('/servers/settings');
          break;
        case 'logs':
          this.$message({
            message: `正在查看 ${row.name} 的日志`,
            type: 'info'
          });
          break;
      }
    },
    submitServerForm() {
      this.$refs.serverForm.validate((valid) => {
        if (valid) {
          this.loading = true;
          setTimeout(() => {
            if (this.serverForm.id) {
              // 编辑现有服务器
              const index = this.serverList.findIndex(s => s.id === this.serverForm.id);
              if (index !== -1) {
                this.serverList[index] = { ...this.serverForm };
                
                this.$message({
                  message: `服务器 ${this.serverForm.name} 信息已更新`,
                  type: 'success'
                });
              }
            } else {
              // 添加新服务器
              const newServer = {
                ...this.serverForm,
                id: this.serverList.length + 1,
                status: 'offline',
                uptime: '0分钟',
                memory: 0,
                cpu: 0,
                players: []
              };
              
              this.serverList.push(newServer);
              
              this.$message({
                message: `服务器 ${newServer.name} 已添加`,
                type: 'success'
              });
            }
            
            this.dialogVisible = false;
            this.loading = false;
          }, 800);
        } else {
          return false;
        }
      });
    }
  }
}
</script>

