<template>
  <div class="page-container">
    <el-card class="main-card">
      <div slot="header" class="clearfix">
        <span>模组配置</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="refreshData">刷新</el-button>
      </div>

      <!-- 模组选择区域 -->
      <div class="mod-select-area" v-loading="loading">
        <el-select v-model="selectedMod" placeholder="请选择要配置的模组" @change="loadModSettings" style="width: 300px;">
          <el-option
            v-for="mod in modsList"
            :key="mod.id"
            :label="mod.name"
            :value="mod.id">
            <template>
              <el-tag size="mini" :type="mod.status === 'enabled' ? 'success' : 'info'" class="status-tag">
                {{ mod.status === 'enabled' ? '启用' : '禁用' }}
              </el-tag>
              <span style="margin-left: 8px">{{ mod.name }}</span>
              <span style="color: #909399; font-size: 12px; margin-left: 5px">v{{ mod.version }}</span>
            </template>
          </el-option>
        </el-select>
      </div>

      <!-- 模组配置内容 -->
      <div v-if="selectedMod" class="mod-settings-content" v-loading="settingsLoading">
        <div class="mod-info-header">
          <div class="mod-info" v-if="currentMod">
            <el-avatar :size="50" :src="currentMod.iconUrl" class="mod-icon"></el-avatar>
            <div class="mod-detail">
              <h3>{{ currentMod.name }} <span class="mod-version">v{{ currentMod.version }}</span></h3>
              <p>作者: {{ currentMod.author }}</p>
            </div>
          </div>
          
          <div class="settings-btns">
            <el-button type="primary" @click="saveSettings" :disabled="!hasChanges">保存配置</el-button>
            <el-button @click="resetSettings">重置</el-button>
          </div>
        </div>
        
        <el-alert
          v-if="!currentMod || !modSettings.length"
          title="此模组没有可配置的选项"
          type="info"
          :closable="false"
          show-icon>
        </el-alert>
        
        <div v-else class="settings-form">
          <el-form ref="settingsForm" :model="settingsForm" label-width="180px" size="small">
            <el-tabs v-model="activeTab" type="border-card">
              <el-tab-pane v-for="group in groupedSettings" :key="group.name" :label="group.label" :name="group.name">
                <div v-for="setting in group.settings" :key="setting.key" class="setting-item">
                  <!-- 文本输入 -->
                  <el-form-item v-if="setting.type === 'text'" :label="setting.label" :prop="setting.key">
                    <el-input 
                      v-model="settingsForm[setting.key]" 
                      :placeholder="setting.placeholder || ''"
                      style="width: 300px">
                    </el-input>
                    <div class="setting-description" v-if="setting.description">{{ setting.description }}</div>
                  </el-form-item>
                  
                  <!-- 数字输入 -->
                  <el-form-item v-else-if="setting.type === 'number'" :label="setting.label" :prop="setting.key">
                    <el-input-number 
                      v-model="settingsForm[setting.key]" 
                      :min="setting.min || 0" 
                      :max="setting.max || 9999"
                      :step="setting.step || 1"
                      style="width: 180px">
                    </el-input-number>
                    <div class="setting-description" v-if="setting.description">{{ setting.description }}</div>
                  </el-form-item>
                  
                  <!-- 开关 -->
                  <el-form-item v-else-if="setting.type === 'boolean'" :label="setting.label" :prop="setting.key">
                    <el-switch v-model="settingsForm[setting.key]"></el-switch>
                    <div class="setting-description" v-if="setting.description">{{ setting.description }}</div>
                  </el-form-item>
                  
                  <!-- 选择框 -->
                  <el-form-item v-else-if="setting.type === 'select'" :label="setting.label" :prop="setting.key">
                    <el-select 
                      v-model="settingsForm[setting.key]" 
                      :placeholder="setting.placeholder || '请选择'"
                      style="width: 300px">
                      <el-option 
                        v-for="option in setting.options" 
                        :key="option.value" 
                        :label="option.label" 
                        :value="option.value">
                      </el-option>
                    </el-select>
                    <div class="setting-description" v-if="setting.description">{{ setting.description }}</div>
                  </el-form-item>
                  
                  <!-- 滑块 -->
                  <el-form-item v-else-if="setting.type === 'slider'" :label="setting.label" :prop="setting.key">
                    <div class="slider-container">
                      <el-slider 
                        v-model="settingsForm[setting.key]" 
                        :min="setting.min || 0" 
                        :max="setting.max || 100"
                        :step="setting.step || 1"
                        :show-stops="setting.showStops"
                        :show-input="setting.showInput"
                        style="width: 400px">
                      </el-slider>
                    </div>
                    <div class="setting-description" v-if="setting.description">{{ setting.description }}</div>
                  </el-form-item>
                  
                  <!-- 颜色选择器 -->
                  <el-form-item v-else-if="setting.type === 'color'" :label="setting.label" :prop="setting.key">
                    <el-color-picker v-model="settingsForm[setting.key]"></el-color-picker>
                    <div class="setting-description" v-if="setting.description">{{ setting.description }}</div>
                  </el-form-item>
                  
                  <!-- 文本域 -->
                  <el-form-item v-else-if="setting.type === 'textarea'" :label="setting.label" :prop="setting.key">
                    <el-input 
                      type="textarea" 
                      v-model="settingsForm[setting.key]" 
                      :rows="4"
                      :placeholder="setting.placeholder || ''"
                      style="width: 400px">
                    </el-input>
                    <div class="setting-description" v-if="setting.description">{{ setting.description }}</div>
                  </el-form-item>
                </div>
              </el-tab-pane>
            </el-tabs>
          </el-form>
        </div>
      </div>
      
      <div v-else class="empty-settings">
        <i class="el-icon-setting"></i>
        <p>请选择一个模组来配置其设置</p>
      </div>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'ModSettings',
  data() {
    return {
      loading: false,
      settingsLoading: false,
      selectedMod: null,
      currentMod: null,
      
      // 模组列表
      modsList: [],
      
      // 配置选项
      modSettings: [],
      settingsForm: {},
      originalSettings: {},
      activeTab: 'general'
    };
  },
  computed: {
    // 将配置分组
    groupedSettings() {
      const groups = {};
      
      this.modSettings.forEach(setting => {
        const groupName = setting.group || 'general';
        const groupLabel = this.getGroupLabel(groupName);
        
        if (!groups[groupName]) {
          groups[groupName] = {
            name: groupName,
            label: groupLabel,
            settings: []
          };
        }
        
        groups[groupName].settings.push(setting);
      });
      
      return Object.values(groups);
    },
    
    // 检查是否有设置变更
    hasChanges() {
      if (!this.originalSettings || Object.keys(this.originalSettings).length === 0) {
        return false;
      }
      
      for (const key in this.settingsForm) {
        if (JSON.stringify(this.settingsForm[key]) !== JSON.stringify(this.originalSettings[key])) {
          return true;
        }
      }
      
      return false;
    }
  },
  created() {
    this.fetchModsList();
    
    // 检查是否有路由参数
    if (this.$route.params.id) {
      this.selectedMod = Number(this.$route.params.id);
      this.loadModSettings(this.selectedMod);
    }
  },
  methods: {
    fetchModsList() {
      this.loading = true;
      
      // 模拟从API获取模组列表
      setTimeout(() => {
        // 生成测试数据
        this.modsList = [
          {
            id: 1,
            name: '无饥饿模式',
            author: 'ModMaster',
            version: '1.3.2',
            status: 'enabled',
            iconUrl: 'https://placehold.co/200x200/409EFF/white?text=MOD'
          },
          {
            id: 2,
            name: '更多生物',
            author: 'CreatureMaker',
            version: '2.1.0',
            status: 'enabled',
            iconUrl: 'https://placehold.co/200x200/67C23A/white?text=MOD'
          },
          {
            id: 3,
            name: '资源显示器',
            author: 'ToolDev',
            version: '1.0.5',
            status: 'disabled',
            iconUrl: 'https://placehold.co/200x200/E6A23C/white?text=MOD'
          },
          {
            id: 4,
            name: '高级建造系统',
            author: 'BuilderPro',
            version: '3.4.1',
            status: 'enabled',
            iconUrl: 'https://placehold.co/200x200/F56C6C/white?text=MOD'
          },
          {
            id: 5,
            name: '季节调整器',
            author: 'SeasonMaster',
            version: '1.2.0',
            status: 'disabled',
            iconUrl: 'https://placehold.co/200x200/909399/white?text=MOD'
          }
        ];
        
        this.loading = false;
      }, 800);
    },
    
    refreshData() {
      this.fetchModsList();
      if (this.selectedMod) {
        this.loadModSettings(this.selectedMod);
      }
    },
    
    loadModSettings(modId) {
      if (!modId) return;
      
      this.settingsLoading = true;
      
      // 获取当前模组信息
      this.currentMod = this.modsList.find(mod => mod.id === modId);
      
      // 模拟从API获取模组配置
      setTimeout(() => {
        // 不同模组有不同配置
        if (modId === 1) { // 无饥饿模式
          this.modSettings = [
            {
              key: 'hungerRate',
              label: '饥饿速度',
              type: 'slider',
              group: 'general',
              min: 0,
              max: 100,
              step: 5,
              showStops: true,
              showInput: true,
              description: '设置玩家饥饿速度百分比，0表示不会饥饿'
            },
            {
              key: 'affectHealth',
              label: '影响健康值',
              type: 'boolean',
              group: 'general',
              description: '饥饿是否影响健康值减少'
            },
            {
              key: 'foodMultiplier',
              label: '食物效果倍数',
              type: 'number',
              group: 'advanced',
              min: 0.5,
              max: 5,
              step: 0.5,
              description: '食物恢复饥饿值的倍数'
            },
            {
              key: 'notificationMessage',
              label: '饥饿提醒消息',
              type: 'text',
              group: 'notifications',
              placeholder: '输入饥饿提醒消息',
              description: '当玩家饥饿时显示的消息'
            }
          ];
          
          // 配置表单默认值
          this.settingsForm = {
            hungerRate: 0,
            affectHealth: false,
            foodMultiplier: 1,
            notificationMessage: '你不会感到饥饿！'
          };
        } else if (modId === 2) { // 更多生物
          this.modSettings = [
            {
              key: 'spawnRate',
              label: '生成频率',
              type: 'slider',
              group: 'general',
              min: 0,
              max: 200,
              step: 10,
              showStops: false,
              showInput: true,
              description: '设置新生物的生成频率百分比'
            },
            {
              key: 'creatureTypes',
              label: '生物类型',
              type: 'select',
              group: 'general',
              options: [
                { label: '全部', value: 'all' },
                { label: '仅和平生物', value: 'peaceful' },
                { label: '仅敌对生物', value: 'hostile' },
                { label: '仅BOSS', value: 'boss' }
              ],
              description: '选择要生成的生物类型'
            },
            {
              key: 'bossHealth',
              label: 'BOSS生命值倍数',
              type: 'number',
              group: 'advanced',
              min: 0.5,
              max: 10,
              step: 0.5,
              description: 'BOSS的生命值倍数'
            },
            {
              key: 'enableTaming',
              label: '允许驯服',
              type: 'boolean',
              group: 'taming',
              description: '是否允许驯服模组添加的生物'
            },
            {
              key: 'tamingDifficulty',
              label: '驯服难度',
              type: 'select',
              group: 'taming',
              options: [
                { label: '简单', value: 'easy' },
                { label: '中等', value: 'medium' },
                { label: '困难', value: 'hard' },
                { label: '极难', value: 'extreme' }
              ],
              description: '设置驯服生物的难度'
            },
            {
              key: 'customSpawnConfig',
              label: '自定义生成配置',
              type: 'textarea',
              group: 'advanced',
              placeholder: '输入JSON格式的自定义生成配置',
              description: '高级用户可以输入JSON格式的自定义生成配置'
            }
          ];
          
          // 配置表单默认值
          this.settingsForm = {
            spawnRate: 100,
            creatureTypes: 'all',
            bossHealth: 1,
            enableTaming: true,
            tamingDifficulty: 'medium',
            customSpawnConfig: ''
          };
        } else if (modId === 3) { // 资源显示器
          this.modSettings = [
            {
              key: 'showOnMap',
              label: '在地图上显示',
              type: 'boolean',
              group: 'display',
              description: '是否在地图上显示资源'
            },
            {
              key: 'showDistance',
              label: '显示距离',
              type: 'boolean',
              group: 'display',
              description: '是否显示与资源的距离'
            },
            {
              key: 'resourceColor',
              label: '资源颜色',
              type: 'color',
              group: 'display',
              description: '设置资源图标的颜色'
            },
            {
              key: 'resourceTypes',
              label: '资源类型',
              type: 'select',
              group: 'resources',
              options: [
                { label: '全部', value: 'all' },
                { label: '仅食物', value: 'food' },
                { label: '仅矿物', value: 'mineral' },
                { label: '仅生物', value: 'creature' },
                { label: '仅建筑材料', value: 'building' }
              ],
              description: '选择要显示的资源类型'
            },
            {
              key: 'updateFrequency',
              label: '更新频率',
              type: 'number',
              group: 'advanced',
              min: 1,
              max: 60,
              step: 1,
              description: '资源信息更新频率（秒）'
            }
          ];
          
          // 配置表单默认值
          this.settingsForm = {
            showOnMap: true,
            showDistance: true,
            resourceColor: '#409EFF',
            resourceTypes: 'all',
            updateFrequency: 5
          };
        } else if (modId === 4) { // 高级建造系统
          this.modSettings = [
            {
              key: 'buildMode',
              label: '建造模式',
              type: 'select',
              group: 'general',
              options: [
                { label: '自由模式', value: 'free' },
                { label: '网格模式', value: 'grid' },
                { label: '对齐模式', value: 'snap' }
              ],
              description: '选择建造模式'
            },
            {
              key: 'resourceCost',
              label: '资源消耗',
              type: 'slider',
              group: 'resources',
              min: 0,
              max: 200,
              step: 10,
              showStops: true,
              showInput: true,
              description: '建造时资源消耗的百分比'
            },
            {
              key: 'enableAllBuildingParts',
              label: '启用所有建筑部件',
              type: 'boolean',
              group: 'parts',
              description: '是否启用所有建筑部件，包括高级部件'
            },
            {
              key: 'buildingDurability',
              label: '建筑耐久度',
              type: 'slider',
              group: 'properties',
              min: 50,
              max: 500,
              step: 50,
              showStops: true,
              showInput: true,
              description: '建筑物的耐久度百分比'
            },
            {
              key: 'customColors',
              label: '自定义颜色',
              type: 'boolean',
              group: 'appearance',
              description: '是否允许自定义建筑颜色'
            },
            {
              key: 'unlockAllRecipes',
              label: '解锁所有配方',
              type: 'boolean',
              group: 'recipes',
              description: '是否解锁所有建筑配方'
            }
          ];
          
          // 配置表单默认值
          this.settingsForm = {
            buildMode: 'snap',
            resourceCost: 100,
            enableAllBuildingParts: false,
            buildingDurability: 100,
            customColors: true,
            unlockAllRecipes: false
          };
        } else if (modId === 5) { // 季节调整器
          this.modSettings = [
            {
              key: 'seasonLength',
              label: '季节长度',
              type: 'number',
              group: 'general',
              min: 1,
              max: 100,
              step: 1,
              description: '每个季节的天数'
            },
            {
              key: 'startSeason',
              label: '起始季节',
              type: 'select',
              group: 'general',
              options: [
                { label: '春季', value: 'spring' },
                { label: '夏季', value: 'summer' },
                { label: '秋季', value: 'autumn' },
                { label: '冬季', value: 'winter' }
              ],
              description: '游戏开始时的季节'
            },
            {
              key: 'rainFrequency',
              label: '降雨频率',
              type: 'slider',
              group: 'weather',
              min: 0,
              max: 100,
              step: 5,
              showStops: false,
              showInput: true,
              description: '降雨的频率百分比'
            },
            {
              key: 'snowFrequency',
              label: '降雪频率',
              type: 'slider',
              group: 'weather',
              min: 0,
              max: 100,
              step: 5,
              showStops: false,
              showInput: true,
              description: '降雪的频率百分比（仅冬季）'
            },
            {
              key: 'temperatureEffect',
              label: '温度效果',
              type: 'select',
              group: 'effects',
              options: [
                { label: '无效果', value: 'none' },
                { label: '轻微效果', value: 'mild' },
                { label: '正常效果', value: 'normal' },
                { label: '强烈效果', value: 'strong' }
              ],
              description: '季节温度对玩家的影响'
            },
            {
              key: 'disableWinter',
              label: '禁用冬季',
              type: 'boolean',
              group: 'advanced',
              description: '是否禁用冬季（跳过冬季）'
            }
          ];
          
          // 配置表单默认值
          this.settingsForm = {
            seasonLength: 20,
            startSeason: 'spring',
            rainFrequency: 30,
            snowFrequency: 70,
            temperatureEffect: 'normal',
            disableWinter: false
          };
        } else {
          // 默认配置为空
          this.modSettings = [];
          this.settingsForm = {};
        }
        
        // 保存原始配置
        this.originalSettings = JSON.parse(JSON.stringify(this.settingsForm));
        
        // 设置默认激活的标签页
        if (this.groupedSettings.length > 0) {
          this.activeTab = this.groupedSettings[0].name;
        }
        
        this.settingsLoading = false;
      }, 1000);
    },
    
    getGroupLabel(groupName) {
      const groupLabels = {
        'general': '常规设置',
        'advanced': '高级设置',
        'resources': '资源设置',
        'display': '显示设置',
        'effects': '效果设置',
        'weather': '天气设置',
        'properties': '属性设置',
        'parts': '部件设置',
        'appearance': '外观设置',
        'recipes': '配方设置',
        'taming': '驯服设置',
        'notifications': '通知设置'
      };
      
      return groupLabels[groupName] || groupName;
    },
    
    saveSettings() {
      this.settingsLoading = true;
      
      // 模拟保存配置
      setTimeout(() => {
        // 保存成功后更新原始配置
        this.originalSettings = JSON.parse(JSON.stringify(this.settingsForm));
        
        this.settingsLoading = false;
        this.$message({
          type: 'success',
          message: '配置保存成功！'
        });
      }, 800);
    },
    
    resetSettings() {
      // 重置为原始配置
      this.settingsForm = JSON.parse(JSON.stringify(this.originalSettings));
      
      this.$message({
        type: 'info',
        message: '配置已重置'
      });
    }
  }
};
</script>

