<template>
  <div class="page-container">
    <el-card class="main-card">
      <div slot="header" class="clearfix">
        <span>模组管理</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="refreshData">刷新</el-button>
      </div>

      <!-- 搜索区域 -->
      <el-form :inline="true" :model="searchForm" class="search-form" size="small">
        <el-form-item label="模组名称">
          <el-input v-model="searchForm.name" placeholder="请输入模组名称"></el-input>
        </el-form-item>
        <el-form-item label="作者">
          <el-input v-model="searchForm.author" placeholder="请输入作者"></el-input>
        </el-form-item>
        <el-form-item label="状态">
          <el-select v-model="searchForm.status" placeholder="请选择状态" clearable>
            <el-option label="启用" value="enabled"></el-option>
            <el-option label="禁用" value="disabled"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" icon="el-icon-search" @click="handleSearch">搜索</el-button>
          <el-button icon="el-icon-refresh" @click="resetSearch">重置</el-button>
        </el-form-item>
      </el-form>

      <!-- 工具栏 -->
      <div class="tool-bar">
        <el-button type="primary" icon="el-icon-plus" @click="handleAdd">添加模组</el-button>
        <el-button type="success" icon="el-icon-check" :disabled="!hasSelection" @click="handleEnable">启用所选</el-button>
        <el-button type="info" icon="el-icon-close" :disabled="!hasSelection" @click="handleDisable">禁用所选</el-button>
        <el-button type="danger" icon="el-icon-delete" :disabled="!hasSelection" @click="handleBatchDelete">删除所选</el-button>
        <el-button type="warning" icon="el-icon-download" @click="handleWorkshopImport">从创意工坊导入</el-button>
      </div>

      <!-- 模组列表 -->
      <div v-loading="loading">
        <el-table
          :data="modsList"
          border
          stripe
          @selection-change="handleSelectionChange"
          style="width: 100%">
          <el-table-column type="selection" width="55"></el-table-column>
          <el-table-column label="状态" width="80" align="center">
            <template slot-scope="scope">
              <el-switch
                :value="scope.row.status === 'enabled'"
                @change="(val) => handleStatusChange(scope.row, val)"
                active-color="#13ce66"
                inactive-color="#ff4949">
              </el-switch>
            </template>
          </el-table-column>
          <el-table-column prop="name" label="模组名称" min-width="180">
            <template slot-scope="scope">
              <div class="mod-info">
                <el-avatar :size="40" :src="scope.row.iconUrl" class="mod-icon"></el-avatar>
                <div class="mod-detail">
                  <div class="mod-name">{{ scope.row.name }}</div>
                  <div class="mod-version">v{{ scope.row.version }}</div>
                </div>
              </div>
            </template>
          </el-table-column>
          <el-table-column prop="author" label="作者" width="120"></el-table-column>
          <el-table-column prop="description" label="描述" min-width="200" show-overflow-tooltip></el-table-column>
          <el-table-column prop="category" label="分类" width="120">
            <template slot-scope="scope">
              <el-tag>{{ scope.row.category }}</el-tag>
            </template>
          </el-table-column>
          <el-table-column prop="size" label="大小" width="90" align="center"></el-table-column>
          <el-table-column prop="updatedAt" label="更新时间" width="180" align="center"></el-table-column>
          <el-table-column label="操作" width="240" align="center">
            <template slot-scope="scope">
              <el-button 
                size="mini" 
                type="primary" 
                icon="el-icon-edit" 
                @click="handleEdit(scope.row)">
                编辑
              </el-button>
              <el-button 
                size="mini" 
                type="success" 
                icon="el-icon-setting" 
                @click="handleConfig(scope.row)">
                配置
              </el-button>
              <el-button 
                size="mini" 
                type="danger" 
                icon="el-icon-delete" 
                @click="handleDelete(scope.row)">
                删除
              </el-button>
            </template>
          </el-table-column>
        </el-table>

        <!-- 分页 -->
        <div class="pagination-container">
          <el-pagination
            @size-change="handleSizeChange"
            @current-change="handleCurrentChange"
            :current-page="pagination.currentPage"
            :page-sizes="[10, 20, 50, 100]"
            :page-size="pagination.pageSize"
            layout="total, sizes, prev, pager, next, jumper"
            :total="pagination.total">
          </el-pagination>
        </div>
      </div>
    </el-card>

    <!-- 添加/编辑模组对话框 -->
    <el-dialog :title="dialogType === 'add' ? '添加模组' : '编辑模组'" :visible.sync="dialogVisible" width="600px">
      <el-form :model="modForm" :rules="modRules" ref="modForm" label-width="100px">
        <el-form-item label="模组名称" prop="name">
          <el-input v-model="modForm.name" placeholder="请输入模组名称"></el-input>
        </el-form-item>
        <el-form-item label="作者" prop="author">
          <el-input v-model="modForm.author" placeholder="请输入作者名称"></el-input>
        </el-form-item>
        <el-form-item label="版本" prop="version">
          <el-input v-model="modForm.version" placeholder="请输入版本号"></el-input>
        </el-form-item>
        <el-form-item label="分类" prop="category">
          <el-select v-model="modForm.category" placeholder="请选择分类">
            <el-option label="游戏玩法" value="gameplay"></el-option>
            <el-option label="物品" value="item"></el-option>
            <el-option label="生物" value="creature"></el-option>
            <el-option label="辅助工具" value="utility"></el-option>
            <el-option label="界面" value="interface"></el-option>
            <el-option label="世界生成" value="worldgen"></el-option>
            <el-option label="其他" value="other"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="描述" prop="description">
          <el-input type="textarea" v-model="modForm.description" rows="4" placeholder="请输入模组描述"></el-input>
        </el-form-item>
        <el-form-item label="模组文件" prop="file" v-if="dialogType === 'add'">
          <el-upload
            class="upload-demo"
            action="#"
            :http-request="customUpload"
            :limit="1"
            :on-exceed="handleExceed"
            :file-list="modForm.fileList">
            <el-button size="small" type="primary">点击上传</el-button>
            <div slot="tip" class="el-upload__tip">只能上传zip文件，且不超过50MB</div>
          </el-upload>
        </el-form-item>
        <el-form-item label="图标" prop="iconUrl">
          <el-upload
            class="avatar-uploader"
            action="#"
            :show-file-list="false"
            :http-request="uploadIcon"
            :before-upload="beforeIconUpload">
            <img v-if="modForm.iconUrl" :src="modForm.iconUrl" class="avatar">
            <i v-else class="el-icon-plus avatar-uploader-icon"></i>
          </el-upload>
        </el-form-item>
        <el-form-item label="状态" prop="status">
          <el-switch
            v-model="modForm.status"
            active-text="启用"
            inactive-text="禁用"
            active-value="enabled"
            inactive-value="disabled">
          </el-switch>
        </el-form-item>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" @click="submitModForm">确定</el-button>
      </span>
    </el-dialog>

    <!-- 导入创意工坊模组对话框 -->
    <el-dialog title="从创意工坊导入模组" :visible.sync="workshopDialogVisible" width="600px">
      <el-form :model="workshopForm" ref="workshopForm" label-width="120px">
        <el-form-item label="创意工坊ID" prop="workshopId">
          <el-input v-model="workshopForm.workshopId" placeholder="请输入Steam创意工坊ID"></el-input>
        </el-form-item>
        <div class="workshop-search-result" v-if="workshopSearchResult">
          <div class="workshop-mod-info">
            <img :src="workshopSearchResult.iconUrl" class="workshop-mod-image">
            <div class="workshop-mod-details">
              <h3>{{ workshopSearchResult.name }}</h3>
              <p>作者: {{ workshopSearchResult.author }}</p>
              <p>更新时间: {{ workshopSearchResult.updatedAt }}</p>
              <p class="workshop-mod-description">{{ workshopSearchResult.description }}</p>
            </div>
          </div>
        </div>
        <div class="workshop-loading" v-else-if="workshopLoading">
          <el-skeleton style="width: 100%" animated>
            <template slot="template">
              <el-skeleton-item variant="image" style="width: 100%; height: 120px" />
              <div style="padding: 14px;">
                <el-skeleton-item variant="h3" style="width: 50%" />
                <div style="display: flex; align-items: center; justify-content: space-between; margin-top: 14px;">
                  <el-skeleton-item variant="text" style="margin-right: 16px;" />
                  <el-skeleton-item variant="text" style="width: 30%;" />
                </div>
              </div>
            </template>
          </el-skeleton>
        </div>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="workshopDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="searchWorkshop" v-if="!workshopSearchResult">搜索</el-button>
        <el-button type="success" @click="importFromWorkshop" v-else>导入模组</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'ModList',
  data() {
    return {
      loading: false,
      // 搜索表单
      searchForm: {
        name: '',
        author: '',
        status: ''
      },
      // 模组列表
      modsList: [],
      // 选中的模组
      selectedMods: [],
      // 分页
      pagination: {
        currentPage: 1,
        pageSize: 10,
        total: 0
      },
      
      // 添加/编辑模组对话框
      dialogVisible: false,
      dialogType: 'add', // 'add' 或 'edit'
      modForm: {
        id: null,
        name: '',
        author: '',
        version: '',
        description: '',
        category: '',
        status: 'enabled',
        iconUrl: '',
        fileList: []
      },
      modRules: {
        name: [
          { required: true, message: '请输入模组名称', trigger: 'blur' },
          { min: 1, max: 50, message: '长度在 1 到 50 个字符', trigger: 'blur' }
        ],
        author: [
          { required: true, message: '请输入作者名称', trigger: 'blur' }
        ],
        version: [
          { required: true, message: '请输入版本号', trigger: 'blur' }
        ],
        category: [
          { required: true, message: '请选择分类', trigger: 'change' }
        ]
      },
      
      // 创意工坊对话框
      workshopDialogVisible: false,
      workshopLoading: false,
      workshopForm: {
        workshopId: ''
      },
      workshopSearchResult: null
    };
  },
  computed: {
    hasSelection() {
      return this.selectedMods.length > 0;
    }
  },
  created() {
    this.fetchModsList();
  },
  methods: {
    fetchModsList() {
      this.loading = true;
      
      // 模拟从API获取模组列表
      setTimeout(() => {
        // 生成测试数据
        this.modsList = [
          {
            id: 1,
            name: '无饥饿模式',
            author: 'ModMaster',
            version: '1.3.2',
            description: '启用后玩家不会饥饿，可以无限生存，适合休闲玩家。',
            category: '游戏玩法',
            status: 'enabled',
            size: '1.2MB',
            updatedAt: '2023-03-15 10:30:45',
            iconUrl: 'https://placehold.co/200x200/409EFF/white?text=MOD'
          },
          {
            id: 2,
            name: '更多生物',
            author: 'CreatureMaker',
            version: '2.1.0',
            description: '增加了30多种全新生物到游戏中，包括新的BOSS和可驯服的宠物。',
            category: '生物',
            status: 'enabled',
            size: '8.5MB',
            updatedAt: '2023-02-28 15:20:10',
            iconUrl: 'https://placehold.co/200x200/67C23A/white?text=MOD'
          },
          {
            id: 3,
            name: '资源显示器',
            author: 'ToolDev',
            version: '1.0.5',
            description: '在游戏界面上显示各类资源的数量和位置，让资源收集更加便捷。',
            category: '辅助工具',
            status: 'disabled',
            size: '0.8MB',
            updatedAt: '2023-01-10 09:15:30',
            iconUrl: 'https://placehold.co/200x200/E6A23C/white?text=MOD'
          },
          {
            id: 4,
            name: '高级建造系统',
            author: 'BuilderPro',
            version: '3.4.1',
            description: '完全重做了建造系统，增加了上百种建筑部件，支持更复杂的建筑结构。',
            category: '游戏玩法',
            status: 'enabled',
            size: '12.3MB',
            updatedAt: '2023-03-05 18:45:22',
            iconUrl: 'https://placehold.co/200x200/F56C6C/white?text=MOD'
          },
          {
            id: 5,
            name: '季节调整器',
            author: 'SeasonMaster',
            version: '1.2.0',
            description: '允许玩家自由控制游戏季节，包括季节长度和天气变化。',
            category: '世界生成',
            status: 'disabled',
            size: '2.1MB',
            updatedAt: '2023-02-15 11:30:00',
            iconUrl: 'https://placehold.co/200x200/909399/white?text=MOD'
          }
        ];
        
        this.pagination.total = 5;
        this.loading = false;
      }, 800);
    },
    
    refreshData() {
      this.searchForm = {
        name: '',
        author: '',
        status: ''
      };
      this.pagination.currentPage = 1;
      this.fetchModsList();
    },
    
    handleSearch() {
      this.pagination.currentPage = 1;
      this.loading = true;
      
      // 模拟搜索
      setTimeout(() => {
        // 根据搜索条件过滤模组列表
        const results = this.modsList.filter(mod => {
          const nameMatch = !this.searchForm.name || mod.name.toLowerCase().includes(this.searchForm.name.toLowerCase());
          const authorMatch = !this.searchForm.author || mod.author.toLowerCase().includes(this.searchForm.author.toLowerCase());
          const statusMatch = !this.searchForm.status || mod.status === this.searchForm.status;
          
          return nameMatch && authorMatch && statusMatch;
        });
        
        this.modsList = results;
        this.pagination.total = results.length;
        this.loading = false;
      }, 500);
    },
    
    resetSearch() {
      this.searchForm = {
        name: '',
        author: '',
        status: ''
      };
      this.fetchModsList();
    },
    
    handleAdd() {
      this.dialogType = 'add';
      this.modForm = {
        id: null,
        name: '',
        author: '',
        version: '',
        description: '',
        category: '',
        status: 'enabled',
        iconUrl: '',
        fileList: []
      };
      this.dialogVisible = true;
    },
    
    handleEdit(mod) {
      this.dialogType = 'edit';
      this.modForm = { ...mod };
      this.dialogVisible = true;
    },
    
    handleConfig(mod) {
      // 跳转到模组配置页面
      this.$router.push({
        name: 'ModSettings',
        params: { id: mod.id },
        query: { name: mod.name }
      });
    },
    
    handleDelete(mod) {
      this.$confirm(`确定要删除模组 "${mod.name}" 吗? 此操作不可恢复!`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.loading = true;
        
        // 模拟删除操作
        setTimeout(() => {
          this.modsList = this.modsList.filter(item => item.id !== mod.id);
          this.pagination.total -= 1;
          this.loading = false;
          
          this.$message({
            type: 'success',
            message: `模组 ${mod.name} 已删除！`
          });
        }, 600);
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消删除'
        });
      });
    },
    
    handleSelectionChange(selected) {
      this.selectedMods = selected;
    },
    
    handleEnable() {
      if (this.selectedMods.length === 0) return;
      
      this.$confirm(`确定要启用选中的 ${this.selectedMods.length} 个模组吗?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'info'
      }).then(() => {
        this.loading = true;
        
        // 模拟启用操作
        setTimeout(() => {
          const selectedIds = this.selectedMods.map(mod => mod.id);
          this.modsList.forEach(mod => {
            if (selectedIds.includes(mod.id)) {
              mod.status = 'enabled';
            }
          });
          
          this.loading = false;
          this.$message({
            type: 'success',
            message: `已启用 ${selectedIds.length} 个模组！`
          });
        }, 600);
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消操作'
        });
      });
    },
    
    handleDisable() {
      if (this.selectedMods.length === 0) return;
      
      this.$confirm(`确定要禁用选中的 ${this.selectedMods.length} 个模组吗?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'info'
      }).then(() => {
        this.loading = true;
        
        // 模拟禁用操作
        setTimeout(() => {
          const selectedIds = this.selectedMods.map(mod => mod.id);
          this.modsList.forEach(mod => {
            if (selectedIds.includes(mod.id)) {
              mod.status = 'disabled';
            }
          });
          
          this.loading = false;
          this.$message({
            type: 'success',
            message: `已禁用 ${selectedIds.length} 个模组！`
          });
        }, 600);
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消操作'
        });
      });
    },
    
    handleBatchDelete() {
      if (this.selectedMods.length === 0) return;
      
      this.$confirm(`确定要删除选中的 ${this.selectedMods.length} 个模组吗? 此操作不可恢复!`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.loading = true;
        
        // 模拟批量删除操作
        setTimeout(() => {
          const selectedIds = this.selectedMods.map(mod => mod.id);
          this.modsList = this.modsList.filter(mod => !selectedIds.includes(mod.id));
          this.pagination.total -= selectedIds.length;
          
          this.loading = false;
          this.$message({
            type: 'success',
            message: `已删除 ${selectedIds.length} 个模组！`
          });
        }, 800);
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消删除'
        });
      });
    },
    
    handleWorkshopImport() {
      this.workshopDialogVisible = true;
      this.workshopForm.workshopId = '';
      this.workshopSearchResult = null;
    },
    
    handleSizeChange(newSize) {
      this.pagination.pageSize = newSize;
      this.fetchModsList();
    },
    
    handleCurrentChange(newPage) {
      this.pagination.currentPage = newPage;
      this.fetchModsList();
    },
    
    customUpload(options) {
      // 模拟上传过程
      this.modForm.fileList = [{
        name: options.file.name,
        size: options.file.size
      }];
    },
    
    handleExceed() {
      this.$message.warning('只能上传一个模组文件');
    },
    
    uploadIcon(options) {
      const file = options.file;
      // 模拟上传图标
      // 在实际应用中，这里应该是上传图片到服务器，然后获取URL
      
      // 使用本地URL预览（仅用于演示）
      const reader = new FileReader();
      reader.onload = (e) => {
        this.modForm.iconUrl = e.target.result;
      };
      reader.readAsDataURL(file);
    },
    
    beforeIconUpload(file) {
      const isImage = file.type.startsWith('image/');
      const isLt2M = file.size / 1024 / 1024 < 2;
      
      if (!isImage) {
        this.$message.error('上传头像图片只能是图片格式!');
      }
      if (!isLt2M) {
        this.$message.error('上传头像图片大小不能超过 2MB!');
      }
      
      return isImage && isLt2M;
    },
    
    submitModForm() {
      this.$refs.modForm.validate((valid) => {
        if (valid) {
          this.loading = true;
          
          if (this.dialogType === 'add') {
            // 模拟添加模组
            setTimeout(() => {
              const newMod = {
                ...this.modForm,
                id: this.modsList.length + 1,
                size: '2.5MB',
                updatedAt: this.formatDate(new Date())
              };
              
              this.modsList.unshift(newMod);
              this.pagination.total += 1;
              
              this.dialogVisible = false;
              this.loading = false;
              
              this.$message({
                type: 'success',
                message: '模组添加成功！'
              });
            }, 1000);
          } else {
            // 模拟编辑模组
            setTimeout(() => {
              const index = this.modsList.findIndex(m => m.id === this.modForm.id);
              if (index !== -1) {
                this.modsList[index] = {
                  ...this.modsList[index],
                  ...this.modForm,
                  updatedAt: this.formatDate(new Date())
                };
              }
              
              this.dialogVisible = false;
              this.loading = false;
              
              this.$message({
                type: 'success',
                message: '模组更新成功！'
              });
            }, 800);
          }
        } else {
          return false;
        }
      });
    },
    
    searchWorkshop() {
      if (!this.workshopForm.workshopId) {
        this.$message.warning('请输入创意工坊ID');
        return;
      }
      
      this.workshopLoading = true;
      
      // 模拟从创意工坊获取数据
      setTimeout(() => {
        this.workshopSearchResult = {
          id: this.workshopForm.workshopId,
          name: '自动寻路模组',
          author: 'SteamUser123',
          description: '这是一个从创意工坊导入的自动寻路模组，可以帮助玩家自动规划路线和寻找资源。',
          updatedAt: '2023-03-10',
          iconUrl: 'https://placehold.co/200x200/F56C6C/white?text=STEAM'
        };
        
        this.workshopLoading = false;
      }, 1500);
    },
    
    importFromWorkshop() {
      this.loading = true;
      
      // 模拟导入
      setTimeout(() => {
        const newMod = {
          id: this.modsList.length + 1,
          name: this.workshopSearchResult.name,
          author: this.workshopSearchResult.author,
          version: '1.0.0',
          description: this.workshopSearchResult.description,
          category: '辅助工具',
          status: 'enabled',
          size: '5.8MB',
          updatedAt: this.formatDate(new Date()),
          iconUrl: this.workshopSearchResult.iconUrl
        };
        
        this.modsList.unshift(newMod);
        this.pagination.total += 1;
        
        this.workshopDialogVisible = false;
        this.loading = false;
        
        this.$message({
          type: 'success',
          message: '模组导入成功！'
        });
      }, 2000);
    },
    
    handleStatusChange(mod, val) {
      const newStatus = val ? 'enabled' : 'disabled';
      
      this.loading = true;
      
      // 模拟更新状态
      setTimeout(() => {
        const index = this.modsList.findIndex(m => m.id === mod.id);
        if (index !== -1) {
          this.modsList[index].status = newStatus;
        }
        
        this.loading = false;
        
        this.$message({
          type: 'success',
          message: `模组已${newStatus === 'enabled' ? '启用' : '禁用'}`
        });
      }, 300);
    },
    
    formatDate(date) {
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      const hours = String(d.getHours()).padStart(2, '0');
      const minutes = String(d.getMinutes()).padStart(2, '0');
      const seconds = String(d.getSeconds()).padStart(2, '0');
      
      return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
    }
  }
};
</script>

