        <el-table-column prop="name" label="玩家名称" min-width="120"></el-table-column>
        <el-table-column prop="role" label="角色" width="100">
          <template slot-scope="scope">
            <el-tag :type="getTagType(scope.row.role)" size="medium">{{ scope.row.role }}</el-tag>
