        <el-table-column prop="status" label="状态" width="100" align="center">
          <template slot-scope="scope">
            <el-tag :type="scope.row.status === 'online' ? 'success' : 'info'" size="medium">
              {{ scope.row.status === 'online' ? '在线' : '离线' }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="lastLogin" label="最后登录时间" width="180" align="center"></el-table-column>
        <el-table-column label="操作" width="260" align="center">
          <template slot-scope="scope">
            <el-button size="mini" type="primary" @click="handleViewDetails(scope.row)">详情</el-button>
            <el-button size="mini" type="success" @click="handleMessage(scope.row)" :disabled="scope.row.status !== 'online'">私信</el-button>
            <el-button size="mini" type="warning" @click="handleKick(scope.row)" :disabled="scope.row.status !== 'online'">踢出</el-button>
            <el-button size="mini" type="danger" @click="handleBan(scope.row)">封禁</el-button>
          </template>
        </el-table-column>
      </el-table>

      <!-- 分页器 -->
      <div class="pagination-container">
        <el-pagination
          @size-change="handleSizeChange"
          @current-change="handleCurrentChange"
          :current-page="currentPage"
          :page-sizes="[10, 20, 50, 100]"
          :page-size="pageSize"
          layout="total, sizes, prev, pager, next, jumper"
          :total="totalPlayers">
        </el-pagination>
      </div>
    </el-card>

    <!-- 玩家详情对话框 -->
    <el-dialog title="玩家详情" :visible.sync="detailsVisible" width="600px">
      <el-descriptions :column="2" border>
        <el-descriptions-item label="玩家名称">{{ currentPlayer.name }}</el-descriptions-item>
        <el-descriptions-item label="角色">{{ currentPlayer.role }}</el-descriptions-item>
        <el-descriptions-item label="累计游戏时长">{{ currentPlayer.playtime }}</el-descriptions-item>
        <el-descriptions-item label="状态">
          <el-tag :type="currentPlayer.status === 'online' ? 'success' : 'info'" size="medium">
            {{ currentPlayer.status === 'online' ? '在线' : '离线' }}
          </el-tag>
        </el-descriptions-item>
        <el-descriptions-item label="所在服务器">{{ currentPlayer.lastServer }}</el-descriptions-item>
        <el-descriptions-item label="最后登录时间">{{ currentPlayer.lastLogin }}</el-descriptions-item>
        <el-descriptions-item label="注册时间" :span="2">{{ currentPlayer.registerTime }}</el-descriptions-item>
        <el-descriptions-item label="生存天数">{{ currentPlayer.surviveDays }}</el-descriptions-item>
        <el-descriptions-item label="死亡次数">{{ currentPlayer.deathCount }}</el-descriptions-item>
        <el-descriptions-item label="IP地址" :span="2">{{ currentPlayer.ipAddress }}</el-descriptions-item>
        <el-descriptions-item label="备注" :span="2">
          {{ currentPlayer.notes || '暂无备注' }}
        </el-descriptions-item>
      </el-descriptions>
      <span slot="footer" class="dialog-footer">
        <el-button type="success" @click="handleMessage(currentPlayer)" :disabled="currentPlayer.status !== 'online'">私信</el-button>
        <el-button type="warning" @click="handleKick(currentPlayer)" :disabled="currentPlayer.status !== 'online'">踢出</el-button>
        <el-button type="danger" @click="handleBan(currentPlayer)">封禁</el-button>
        <el-button @click="detailsVisible = false">关闭</el-button>
      </span>
    </el-dialog>
  </div>
</template>

