        },
        {
          id: 8,
          avatar: 'https://cube.elemecdn.com/0/88/03b0d39583f48206768a7534e55bcpng.png',
          name: '大力士沃尔夫冈',
          role: '沃尔夫冈',
          lastServer: 'PVP服务器',
          playtime: '96小时',
          status: 'offline',
          lastLogin: '2023-03-20 20:10:05',
          registerTime: '2023-01-25 16:30:00',
          surviveDays: 35,
          deathCount: 22,
          ipAddress: '192.168.1.108',
          notes: 'PVP积极玩家'
        }
      ],
      filteredPlayers: [],
      currentPage: 1,
      pageSize: 10,
      totalPlayers: 0,
      detailsVisible: false,
      currentPlayer: {}
    }
  },
  created() {
    this.initData();
  },
  methods: {
    initData() {
      this.loading = true;
      setTimeout(() => {
        this.filteredPlayers = [...this.players];
        this.totalPlayers = this.players.length;
        this.loading = false;
      }, 500);
    },
    refreshData() {
      this.loading = true;
      setTimeout(() => {
        this.$message({
          message: '数据已刷新',
          type: 'success'
        });
        this.loading = false;
      }, 800);
    },
    onSearch() {
      this.loading = true;
      setTimeout(() => {
        this.filteredPlayers = this.players.filter(player => {
          let matchName = true;
          let matchServer = true;
          let matchStatus = true;

          if (this.searchForm.name) {
            matchName = player.name.includes(this.searchForm.name);
          }
          
          if (this.searchForm.server) {
            matchServer = player.lastServer === this.searchForm.server;
          }
          
          if (this.searchForm.status) {
            matchStatus = player.status === this.searchForm.status;
          }
          
          return matchName && matchServer && matchStatus;
        });
        this.totalPlayers = this.filteredPlayers.length;
        this.currentPage = 1;
        this.loading = false;
      }, 500);
    },
    resetSearch() {
      this.searchForm = {
        name: '',
        server: '',
        status: ''
      };
      this.initData();
    },
    handleSizeChange(val) {
      this.pageSize = val;
    },
    handleCurrentChange(val) {
      this.currentPage = val;
    },
    getTagType(role) {
      const roleMap = {
        '薇诺娜': 'warning',
        '沃利': 'success',
        '麦斯威尔': 'info',
        '温蒂': 'primary',
        '旺达': 'warning',
        '韦伯': 'danger',
        '薇格弗德': 'danger',
        '沃尔夫冈': 'primary'
      };
      return roleMap[role] || '';
    },
    handleViewDetails(row) {
      this.currentPlayer = { ...row };
      this.detailsVisible = true;
    },
    handleMessage(player) {
      this.$prompt(`发送消息给玩家 ${player.name}`, '私信', {
        confirmButtonText: '发送',
        cancelButtonText: '取消',
        inputPlaceholder: '请输入消息内容'
      }).then(({ value }) => {
        this.$message({
          type: 'success',
          message: `消息已发送给 ${player.name}！`
        });
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消发送'
        });
      });
    },
    handleKick(player) {
      this.$confirm(`确定要将玩家 "${player.name}" 踢出服务器吗?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.$message({
          type: 'success',
          message: `已将玩家 ${player.name} 踢出服务器！`
        });
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消操作'
        });
      });
    },
    handleBan(player) {
      this.$confirm(`确定要封禁玩家 "${player.name}" 吗?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.$message({
          type: 'success',
          message: `已封禁玩家 ${player.name}！`
        });
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消操作'
        });
      });
    }
  }
}
</script>

