<template>
  <div class="page-container">
    <el-card class="main-card">
      <div slot="header" class="clearfix">
        <span>封禁列表</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="refreshData">刷新</el-button>
      </div>

      <!-- 搜索栏 -->
      <div class="search-bar">
        <el-form :inline="true" :model="searchForm" class="form-inline">
          <el-form-item label="玩家名称">
            <el-input v-model="searchForm.name" placeholder="输入玩家名称" clearable></el-input>
          </el-form-item>
          <el-form-item label="封禁类型">
            <el-select v-model="searchForm.banType" placeholder="选择封禁类型" clearable>
              <el-option label="账号封禁" value="accountBan"></el-option>
              <el-option label="IP封禁" value="ipBan"></el-option>
              <el-option label="聊天封禁" value="chatBan"></el-option>
            </el-select>
          </el-form-item>
          <el-form-item label="状态">
            <el-select v-model="searchForm.status" placeholder="封禁状态" clearable>
              <el-option label="活跃" value="active"></el-option>
              <el-option label="已过期" value="expired"></el-option>
            </el-select>
          </el-form-item>
          <el-form-item>
            <el-button type="primary" @click="onSearch">查询</el-button>
            <el-button @click="resetSearch">重置</el-button>
          </el-form-item>
        </el-form>
      </div>

      <!-- 工具栏 -->
      <div class="tool-bar">
        <el-button type="primary" icon="el-icon-plus" @click="handleAddBan">新增封禁</el-button>
        <el-button type="danger" icon="el-icon-delete" :disabled="!multipleSelection.length" @click="handleBatchDelete">批量删除</el-button>
      </div>

      <!-- 封禁表格 -->
      <el-table
        :data="filteredBans"
        v-loading="loading"
        style="width: 100%"
        border
        @selection-change="handleSelectionChange">
        <el-table-column type="selection" width="55"></el-table-column>
        <el-table-column prop="name" label="玩家名称" min-width="120"></el-table-column>
        <el-table-column prop="banType" label="封禁类型" width="120">
          <template slot-scope="scope">
            <el-tag :type="getBanTypeTag(scope.row.banType)">{{ getBanTypeText(scope.row.banType) }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="reason" label="封禁原因" min-width="180"></el-table-column>
        <el-table-column prop="bannedBy" label="操作人" width="120"></el-table-column>
        <el-table-column prop="banTime" label="封禁时间" width="180" align="center"></el-table-column>
        <el-table-column prop="expireTime" label="到期时间" width="180" align="center"></el-table-column>
        <el-table-column prop="status" label="状态" width="90" align="center">
          <template slot-scope="scope">
            <el-tag :type="scope.row.status === 'active' ? 'danger' : 'info'">
              {{ scope.row.status === 'active' ? '活跃' : '已过期' }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column label="操作" width="200" align="center">
          <template slot-scope="scope">
            <el-button size="mini" type="primary" @click="handleEdit(scope.row)">编辑</el-button>
            <el-button size="mini" type="success" @click="handleUnban(scope.row)" :disabled="scope.row.status !== 'active'">解封</el-button>
            <el-button size="mini" type="danger" @click="handleDelete(scope.row)">删除</el-button>
          </template>
        </el-table-column>
      </el-table>

      <!-- 分页器 -->
      <div class="pagination-container">
        <el-pagination
          @size-change="handleSizeChange"
          @current-change="handleCurrentChange"
          :current-page="currentPage"
          :page-sizes="[10, 20, 50, 100]"
          :page-size="pageSize"
          layout="total, sizes, prev, pager, next, jumper"
          :total="totalBans">
        </el-pagination>
      </div>
    </el-card>

    <!-- 新增/编辑封禁对话框 -->
    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="600px">
      <el-form :model="banForm" :rules="banRules" ref="banForm" label-width="100px">
        <el-form-item label="玩家名称" prop="name">
          <el-autocomplete
            v-model="banForm.name"
            :fetch-suggestions="queryPlayers"
            placeholder="请输入玩家名称"
            style="width: 100%">
          </el-autocomplete>
        </el-form-item>
        <el-form-item label="封禁类型" prop="banType">
          <el-select v-model="banForm.banType" placeholder="请选择封禁类型" style="width: 100%">
            <el-option label="账号封禁" value="accountBan"></el-option>
            <el-option label="IP封禁" value="ipBan"></el-option>
            <el-option label="聊天封禁" value="chatBan"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="封禁原因" prop="reason">
          <el-input type="textarea" v-model="banForm.reason" :rows="3" placeholder="请输入封禁原因"></el-input>
        </el-form-item>
        <el-form-item label="封禁时长" prop="duration">
          <el-select v-model="banForm.duration" placeholder="请选择封禁时长" style="width: 100%">
            <el-option label="1天" value="1d"></el-option>
            <el-option label="3天" value="3d"></el-option>
            <el-option label="7天" value="7d"></el-option>
            <el-option label="30天" value="30d"></el-option>
            <el-option label="永久" value="permanent"></el-option>
            <el-option label="自定义" value="custom"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="截止日期" v-if="banForm.duration === 'custom'" prop="customEndDate">
          <el-date-picker
            v-model="banForm.customEndDate"
            type="datetime"
            placeholder="选择封禁结束日期"
            style="width: 100%">
          </el-date-picker>
        </el-form-item>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" @click="submitBanForm">确认</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'BanList',
  data() {
    return {
      loading: false,
      searchForm: {
        name: '',
        banType: '',
        status: ''
      },
      // 模拟封禁列表数据
      bans: [
        {
          id: 1,
          name: '恶意玩家A',
          banType: 'accountBan',
          reason: '使用自动脚本，违反游戏规则',
          bannedBy: '管理员小明',
          banTime: '2023-03-15 14:30:22',
          expireTime: '2023-04-15 14:30:22',
          status: 'active'
        },
        {
          id: 2,
          name: '恶意玩家B',
          banType: 'ipBan',
          reason: '多次使用作弊模组',
          bannedBy: '管理员小红',
          banTime: '2023-03-10 09:15:40',
          expireTime: '永久',
          status: 'active'
        },
        {
          id: 3,
          name: '恶意玩家C',
          banType: 'chatBan',
          reason: '聊天频道发送不当言论',
          bannedBy: '管理员小蓝',
          banTime: '2023-03-18 16:45:12',
          expireTime: '2023-03-25 16:45:12',
          status: 'active'
        },
        {
          id: 4,
          name: '普通玩家D',
          banType: 'chatBan',
          reason: '聊天频道发广告',
          bannedBy: '管理员小绿',
          banTime: '2023-02-20 11:30:05',
          expireTime: '2023-02-23 11:30:05',
          status: 'expired'
        },
        {
          id: 5,
          name: '恶意玩家E',
          banType: 'accountBan',
          reason: '恶意破坏其他玩家建筑',
          bannedBy: '管理员小明',
          banTime: '2023-03-05 10:20:15',
          expireTime: '2023-03-12 10:20:15',
          status: 'expired'
        }
      ],
      filteredBans: [],
      multipleSelection: [],
      currentPage: 1,
      pageSize: 10,
      totalBans: 0,
      
      // 对话框相关
      dialogVisible: false,
      dialogTitle: '新增封禁',
      banForm: {
        id: null,
        name: '',
        banType: 'accountBan',
        reason: '',
        duration: '7d',
        customEndDate: null
      },
      banRules: {
        name: [
          { required: true, message: '请输入玩家名称', trigger: 'blur' }
        ],
        banType: [
          { required: true, message: '请选择封禁类型', trigger: 'change' }
        ],
        reason: [
          { required: true, message: '请输入封禁原因', trigger: 'blur' }
        ],
        duration: [
          { required: true, message: '请选择封禁时长', trigger: 'change' }
        ],
        customEndDate: [
          { required: true, message: '请选择截止日期', trigger: 'change' }
        ]
      },
      
      // 模拟玩家列表数据用于自动补全
      players: [
        { value: '猪王爱烤肉' },
        { value: '沃利大厨' },
        { value: '麦斯威尔' },
        { value: '温蒂的鬼魂' },
        { value: '旺达时光机' },
        { value: '韦伯蜘蛛窝' },
        { value: '薇格弗德火女' },
        { value: '大力士沃尔夫冈' }
      ]
    }
  },
  created() {
    this.initData();
  },
  methods: {
    initData() {
      this.loading = true;
      setTimeout(() => {
        this.filteredBans = [...this.bans];
        this.totalBans = this.bans.length;
        this.loading = false;
      }, 500);
    },
    refreshData() {
      this.loading = true;
      setTimeout(() => {
        this.$message({
          message: '数据已刷新',
          type: 'success'
        });
        this.loading = false;
      }, 800);
    },
    onSearch() {
      this.loading = true;
      setTimeout(() => {
        this.filteredBans = this.bans.filter(ban => {
          let matchName = true;
          let matchType = true;
          let matchStatus = true;

          if (this.searchForm.name) {
            matchName = ban.name.includes(this.searchForm.name);
          }
          
          if (this.searchForm.banType) {
            matchType = ban.banType === this.searchForm.banType;
          }
          
          if (this.searchForm.status) {
            matchStatus = ban.status === this.searchForm.status;
          }
          
          return matchName && matchType && matchStatus;
        });
        this.totalBans = this.filteredBans.length;
        this.currentPage = 1;
        this.loading = false;
      }, 500);
    },
    resetSearch() {
      this.searchForm = {
        name: '',
        banType: '',
        status: ''
      };
      this.initData();
    },
    handleSizeChange(val) {
      this.pageSize = val;
    },
    handleCurrentChange(val) {
      this.currentPage = val;
    },
    handleSelectionChange(val) {
      this.multipleSelection = val;
    },
    getBanTypeText(type) {
      const typeMap = {
        'accountBan': '账号封禁',
        'ipBan': 'IP封禁',
        'chatBan': '聊天封禁'
      };
      return typeMap[type] || type;
    },
    getBanTypeTag(type) {
      const typeMap = {
        'accountBan': 'danger',
        'ipBan': 'warning',
        'chatBan': 'info'
      };
      return typeMap[type] || '';
    },
    handleAddBan() {
      this.dialogTitle = '新增封禁';
      this.banForm = {
        id: null,
        name: '',
        banType: 'accountBan',
        reason: '',
        duration: '7d',
        customEndDate: null
      };
      this.dialogVisible = true;
    },
    handleEdit(row) {
      this.dialogTitle = '编辑封禁';
      this.banForm = {
        id: row.id,
        name: row.name,
        banType: row.banType,
        reason: row.reason,
        duration: row.expireTime === '永久' ? 'permanent' : 'custom',
        customEndDate: row.expireTime !== '永久' ? new Date(row.expireTime) : null
      };
      this.dialogVisible = true;
    },
    handleUnban(row) {
      this.$confirm(`确定要解除对玩家 "${row.name}" 的封禁吗?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        // 模拟解除封禁操作
        const index = this.bans.findIndex(ban => ban.id === row.id);
        if (index !== -1) {
          this.bans[index].status = 'expired';
          this.filteredBans = [...this.bans];
        }
        this.$message({
          type: 'success',
          message: `已解除对玩家 ${row.name} 的封禁！`
        });
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消操作'
        });
      });
    },
    handleDelete(row) {
      this.$confirm(`确定要删除对玩家 "${row.name}" 的封禁记录吗?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        // 模拟删除操作
        const index = this.bans.findIndex(ban => ban.id === row.id);
        if (index !== -1) {
          this.bans.splice(index, 1);
          this.filteredBans = [...this.bans];
          this.totalBans = this.bans.length;
        }
        this.$message({
          type: 'success',
          message: `已删除对玩家 ${row.name} 的封禁记录！`
        });
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消操作'
        });
      });
    },
    handleBatchDelete() {
      if (this.multipleSelection.length === 0) {
        this.$message.warning('请选择要删除的封禁记录');
        return;
      }
      
      this.$confirm(`确定要删除选中的 ${this.multipleSelection.length} 条封禁记录吗?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        // 模拟批量删除操作
        const ids = this.multipleSelection.map(item => item.id);
        this.bans = this.bans.filter(ban => !ids.includes(ban.id));
        this.filteredBans = [...this.bans];
        this.totalBans = this.bans.length;
        this.$message({
          type: 'success',
          message: `成功删除 ${ids.length} 条封禁记录！`
        });
      }).catch(() => {
        this.$message({
          type: 'info',
          message: '已取消操作'
        });
      });
    },
    queryPlayers(queryString, cb) {
      const results = queryString 
        ? this.players.filter(player => player.value.toLowerCase().includes(queryString.toLowerCase()))
        : this.players;
      cb(results);
    },
    submitBanForm() {
      this.$refs.banForm.validate((valid) => {
        if (valid) {
          // 模拟表单提交
          this.loading = true;
          setTimeout(() => {
            if (this.banForm.id) {
              // 编辑现有记录
              const index = this.bans.findIndex(ban => ban.id === this.banForm.id);
              if (index !== -1) {
                // 计算过期时间
                let expireTime = '永久';
                if (this.banForm.duration !== 'permanent') {
                  if (this.banForm.duration === 'custom' && this.banForm.customEndDate) {
                    expireTime = this.formatDate(this.banForm.customEndDate);
                  } else {
                    const days = parseInt(this.banForm.duration);
                    const date = new Date();
                    date.setDate(date.getDate() + days);
                    expireTime = this.formatDate(date);
                  }
                }
                
                this.bans[index] = {
                  ...this.bans[index],
                  name: this.banForm.name,
                  banType: this.banForm.banType,
                  reason: this.banForm.reason,
                  expireTime: expireTime
                };
                
                this.$message({
                  message: '封禁记录已更新',
                  type: 'success'
                });
              }
            } else {
              // 添加新记录
              // 计算过期时间
              let expireTime = '永久';
              if (this.banForm.duration !== 'permanent') {
                if (this.banForm.duration === 'custom' && this.banForm.customEndDate) {
                  expireTime = this.formatDate(this.banForm.customEndDate);
                } else {
                  const days = parseInt(this.banForm.duration);
                  const date = new Date();
                  date.setDate(date.getDate() + days);
                  expireTime = this.formatDate(date);
                }
              }
              
              const newBan = {
                id: this.bans.length + 1,
                name: this.banForm.name,
                banType: this.banForm.banType,
                reason: this.banForm.reason,
                bannedBy: '当前管理员',
                banTime: this.formatDate(new Date()),
                expireTime: expireTime,
                status: 'active'
              };
              
              this.bans.unshift(newBan);
              this.$message({
                message: '已成功添加封禁记录',
                type: 'success'
              });
            }
            
            this.filteredBans = [...this.bans];
            this.totalBans = this.bans.length;
            this.dialogVisible = false;
            this.loading = false;
          }, 800);
        } else {
          return false;
        }
      });
    },
    formatDate(date) {
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      const hours = String(d.getHours()).padStart(2, '0');
      const minutes = String(d.getMinutes()).padStart(2, '0');
      const seconds = String(d.getSeconds()).padStart(2, '0');
      
      return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
    }
  }
}
</script>

<style scoped>
.page-container {
  padding: 20px;
}

.main-card {
  margin-bottom: 20px;
  box-shadow: 0 2px 12px 0 rgba(0, 0, 0, 0.1);
  border-radius: 4px;
}

.search-bar {
  margin-bottom: 20px;
}

.tool-bar {
  margin-bottom: 20px;
}

.pagination-container {
  margin-top: 20px;
  text-align: right;
}

.el-tag {
  margin-right: 5px;
}

.el-button+.el-button {
  margin-left: 5px;
}
</style> 